// Schemes that don't hand out money themselves but can make a loan easier.
export const ENABLERS = {
  scheme_cgtmse: 'Collateral-free credit guarantee — ask the lender whether your loan can be covered by CGTMSE so you do not need to pledge security.',
};

const isSpecial = (t, profile) =>
  (t.specialCategories || []).includes(profile.category) || (t.specialIfFemale && profile.gender === 'female');

// Resolve a terms object for one user/situation into plain numbers (or null =
// unknown). `ctx` = { sector, area, profile }.
export function resolveTerms(schemeId, ctx) {
  const t = CURATED_TERMS[schemeId];
  if (!t) return null;
  const c = { sector: ctx.sector, area: ctx.area, special: isSpecial(t, ctx.profile) };
  const grant = t.grant ? {
    kind: t.grant.kind,
    pct: t.grant.pct ? t.grant.pct(c) : null,
    cap: t.grant.cap ?? null,
    amount: t.grant.amount ?? null,
    timing: t.grant.timing,
    isCeiling: Boolean(t.grantIsCeiling),
  } : null;
  return {
    schemeId,
    fundingType: t.fundingType,
    sizeMin: t.sizeMin ?? null,
    sizeMax: typeof t.sizeMax === 'function' ? t.sizeMax(c) : (t.sizeMax ?? null),
    ownContributionPct: t.ownContributionPct ? t.ownContributionPct(c) : null,
    grant,
    rate: t.rate,
    tenureDefault: t.tenureDefault ?? null,
    tenureAssumed: Boolean(t.tenureAssumed),
    verifyWithBank: t.verifyWithBank || [],
    note: t.note || null,
    selfConfirm: t.selfConfirm || null,
    sources: t.sources || {},
  };
}

// The interest rate to compute with, or null when it cannot honestly be known.
// Returns { value, isEstimate, label, basis }.
export function pickRate(rate, { gender, quotedRate }) {
  if (!rate) return null;
  if (rate.kind === 'fixed') return { value: rate.value, isEstimate: false, label: `${rate.value}%`, basis: 'scheme rate' };
  if (rate.kind === 'by_gender') {
    const v = gender === 'female' ? rate.female : rate.other;
    return { value: v, isEstimate: false, label: `${v}%`, basis: gender === 'female' ? 'scheme rate for women' : 'scheme rate' };
  }
  if (rate.kind === 'range') {
    const mid = (rate.min + rate.max) / 2;
    return { value: mid, isEstimate: true, label: `~${mid}% (range ${rate.min}%–${rate.max}%)`, basis: 'midpoint of the published range — the lender sets the final rate' };
  }
  // 'unspecified': only the user's own bank quote may be used.
  if (Number.isFinite(quotedRate)) return { value: quotedRate, isEstimate: false, label: `${quotedRate}%`, basis: 'the rate you told us your bank quoted' };
  return null;
}

// ---- catalogue (AI-extracted, unverified) loan rows → same shape ----------
export function catalogueTerms(row) {
  const num = (v) => (Number.isFinite(Number(v)) && v !== null ? Number(v) : null);
  const pos = (v) => { const n = num(v); return n && n > 0 ? n : null; }; // 0 in the extraction means "not specified"
  let rate = { kind: 'unspecified', note: 'The official scheme text does not give a usable interest rate.' };
  const rt = row.rate_type;
  const fixed = num(row.interest_rate), lo = num(row.interest_rate_min), hi = num(row.interest_rate_max);
  if (rt === 'official_fixed' && fixed !== null) rate = { kind: 'fixed', value: fixed };
  else if (rt === 'official_range' && lo !== null && hi !== null) rate = { kind: 'range', min: lo, max: hi };
  else if (rt === 'subsidy') {
    const base = fixed ?? (lo !== null && hi !== null ? (lo + hi) / 2 : null);
    const sub = num(row.interest_subsidy_pct);
    if (base !== null) rate = { kind: 'fixed', value: Math.max(0, base - (sub || 0)), derived: true };
  }
  return {
    schemeId: row.slug,
    fundingType: 'loan',
    sizeMin: pos(row.loan_amount_min),
    sizeMax: pos(row.loan_amount_max),
    ownContributionPct: null,
    grant: null,
    rate,
    tenureDefault: null,
    tenureMin: pos(row.tenure_min_months),
    tenureMax: pos(row.tenure_max_months),
    verifyWithBank: ['everything'],
    sources: { all: 'ai_extracted' },
  };
}
